-- 339-sg-footer-appstore-badge-and-move-social.sql
-- SG storefront footer restructure (data-only, CMS blocks; SG-scoped, idempotent).
--   1. Footer Row 1 "Contact Us Information" (block_footer_column5): replace the
--      social-media icon strip with the official "Download on the App Store" badge
--      (linking to https://apps.apple.com/app/tertiary-courses/id6787036413).
--   2. Footer Row 2 "Information" (block_footer_row2_column5): add the social-media
--      icon strip directly below the Sitemap link.
-- Both statements are scoped by SG-only content signatures so they no-op on the
-- MY / GH partner databases (same codebase, different DB). Badge artwork is inlined
-- as the official Apple SVG so there is no dependence on the media volume.
-- After deploy, flush the CMS/full cache (Redis) for the change to show — the
-- deploy entrypoint clears file caches only. See memory
-- feedback_prod_cms_migration_needs_redis_flush.

-- 1. Row 1: swap social strip -> App Store badge (idempotent: no-op once badge present)
UPDATE cms_block SET content = REPLACE(content, UNHEX(''), UNHEX('')) WHERE content LIKE '%12 Woodlands Square%' AND content LIKE CONCAT('%', UNHEX('736f6369616c2d6c696e6b732069622d777261707065722d2d737175617265'), '%');

-- 2. Row 2: add social strip below Sitemap (idempotent: guarded by NOT LIKE social strip)
UPDATE cms_block SET content = REPLACE(content, UNHEX('536974656d61703c2f613e3c2f6c693e0d0a3c2f756c3e'), UNHEX('')) WHERE content LIKE CONCAT('%', UNHEX('7465727469617279636f75727365732e636f6d2e73672f736665632e68746d6c'), '%') AND content NOT LIKE CONCAT('%', UNHEX('736f6369616c2d6c696e6b732069622d777261707065722d2d737175617265'), '%');
